# Spec 132: (1) viability after KO of the 68 tumour-selected TFs vs the other chromVAR TFs in the 21 mesothelioma lines (DepMap 24Q4 Chronos gene effect; < 0 = impaired viability);
#           (2) which of the 68 TFs are more required in mesothelioma than in the other DepMap lines.
#   A  per-TF median gene effect over the mesothelioma lines, selected vs other TFs (Wilcoxon, one- and two-sided)
#   B  the 68 TFs: mesothelioma minus other lines (difference of medians) vs one-sided Wilcoxon p (more negative in mesothelioma), BH over the 68
# env: BACKGROUND = all (default; every other chromVAR TF) | expressed (other TFs passing the expression filter used for the 68: log2 mean expression > 0.5 in at least one tumour, scRNA-seq;
#      from R1_Q8/rna_log2mean_per_sample.csv, RNA_PER_SAMPLE) -> outputs get the suffix _expressedBG
# needs: DepMap 24Q4 (DEPMAP_DIR), ARCHR_DIR (selected_TF.rds, TF_activators_genescore.rds)
# outputs: spec132_selected_TF_meso_specificity.csv, fig48_selected_TFs_viability_meso.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 220)
DM <- Sys.getenv("DEPMAP_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/DepMap_24Q4"); AR <- Sys.getenv("ARCHR_DIR", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/tumor_compartment/scatac_ArchR")
fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 1), formatC(p, format = "g", digits = 2))); SC <- "#eb6834"; BC <- "grey60"
sel <- readRDS(file.path(AR, "selected_TF.rds")); suppressPackageStartupMessages(library(S4Vectors)); allTF <- union(unique(as.character(readRDS(file.path(AR, "TF_activators_genescore.rds"))$GeneScoreMatrix_name)), sel)
hd <- strsplit(readLines(file.path(DM, "CRISPRGeneEffect.csv"), n = 1), ",")[[1]]; sym <- sub(" \\(.*", "", hd); tf <- intersect(allTF, sym); rdm <- function(f) { x <- data.table::fread(file.path(DM, f), select = c(1, match(tf, sym)), data.table = FALSE); M <- as.matrix(x[, -1]); dimnames(M) <- list(x[[1]], tf); M }
GE <- rdm("CRISPRGeneEffect.csv"); GD <- rdm("CRISPRGeneDependency.csv"); mo <- read.csv(file.path(DM, "Model.csv"), stringsAsFactors = FALSE); mo <- mo[match(rownames(GE), mo$ModelID), ]; is_m <- grepl("esotheli", paste(mo$OncotreePrimaryDisease, mo$OncotreeSubtype))
BG <- Sys.getenv("BACKGROUND", "all"); SFX <- if (BG == "all") "" else "_expressedBG"; BGLAB <- if (BG == "all") "other TFs" else "other expressed TFs"
if (BG == "expressed") { ps <- read.csv(Sys.getenv("RNA_PER_SAMPLE", unset = "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/mesothelioma/scATAC_PM/git_repo_claude/R1_Q8/rna_log2mean_per_sample.csv"), row.names = 1, check.names = FALSE); tum <- setdiff(colnames(ps), "normal_pleura"); expd <- rownames(ps)[apply(ps[, tum], 1, function(x) any(x > 0.5))]
  cat(sprintf("expression filter: %d of %d TFs expressed in >= 1 of %d tumours; selected passing: %d of %d; background before: %d, after: %d\n", length(expd), nrow(ps), length(tum), sum(sel %in% expd), length(sel), sum(!colnames(GE) %in% sel), sum(!colnames(GE) %in% sel & colnames(GE) %in% expd))); keep <- colnames(GE) %in% sel | colnames(GE) %in% expd; GE <- GE[, keep]; GD <- GD[, keep] }
E <- GE[is_m, ]; rownames(E) <- mo$StrippedCellLineName[is_m]; O <- GE[!is_m, ]; s <- colnames(E) %in% sel; med <- apply(E, 2, median, na.rm = TRUE); ndep <- colSums(GD[is_m, ] > 0.5, na.rm = TRUE)
## (1) selected vs the other TFs
w2 <- wilcox.test(med[s], med[!s]); w1 <- wilcox.test(med[s], med[!s], alternative = "less"); wa <- wilcox.test(as.vector(E[, s]), as.vector(E[, !s]), alternative = "less")
PL <- data.frame(line = rownames(E), diff = apply(E, 1, function(v) median(v[s], na.rm = TRUE) - median(v[!s], na.rm = TRUE)), diff_mean = apply(E, 1, function(v) mean(v[s], na.rm = TRUE) - mean(v[!s], na.rm = TRUE)), p = apply(E, 1, function(v) wilcox.test(v[s], v[!s], alternative = "less")$p.value)); PL <- PL[order(PL$diff), ]
sr <- wilcox.test(PL$diff, alternative = "less"); srm <- wilcox.test(PL$diff_mean, alternative = "less"); cat3 <- function(n) cut(n, c(-1, 0, 4, 10, 21), labels = c("no line", "1-4 lines", "5-10 lines", "11-21 lines")); TB <- rbind(selected = prop.table(table(cat3(ndep[s]))), other = prop.table(table(cat3(ndep[!s])))); ch <- fisher.test(table(s, ndep >= 1), alternative = "greater"); ch5 <- fisher.test(table(s, ndep >= 5), alternative = "greater")
cat(sprintf("68 selected vs %d other TFs, 21 mesothelioma lines\n  median of per-TF medians: %.3f vs %.3f; Wilcoxon two-sided p %s, one-sided (selected lower) p %s\n  mean gene effect: %.3f vs %.3f\n  all TF x line values, one-sided p %s\n  per line: selected lower (medians) in %d/21, signed-rank p %s; lower (means) in %d/21, signed-rank p %s\n  dependency in >= 1 line: %.0f%% vs %.0f%% (Fisher one-sided p %s); in >= 5 lines: %.0f%% vs %.0f%% (p %s)\n",
            sum(!s), median(med[s]), median(med[!s]), fp(w2$p.value), fp(w1$p.value), mean(E[, s], na.rm = TRUE), mean(E[, !s], na.rm = TRUE), fp(wa$p.value), sum(PL$diff < 0), fp(sr$p.value), sum(PL$diff_mean < 0), fp(srm$p.value), 100 * mean(ndep[s] >= 1), 100 * mean(ndep[!s] >= 1), fp(ch$p.value), 100 * mean(ndep[s] >= 5), 100 * mean(ndep[!s] >= 5), fp(ch5$p.value)))
## (2) mesothelioma-specific effect of each selected TF
SP <- do.call(rbind, lapply(colnames(E)[s], function(k) data.frame(TF = k, meso_median = median(E[, k], na.rm = TRUE), other_median = median(O[, k], na.rm = TRUE), diff = median(E[, k], na.rm = TRUE) - median(O[, k], na.rm = TRUE), p_more_required = wilcox.test(E[, k], O[, k], alternative = "less")$p.value, p_less_required = wilcox.test(E[, k], O[, k], alternative = "greater")$p.value,
                                                                       n_dep_meso = sum(GD[is_m, k] > 0.5, na.rm = TRUE), pct_dep_meso = 100 * mean(GD[is_m, k] > 0.5, na.rm = TRUE), pct_dep_other = 100 * mean(GD[!is_m, k] > 0.5, na.rm = TRUE))))
SP$fdr_more <- p.adjust(SP$p_more_required, "BH"); SP$fdr_less <- p.adjust(SP$p_less_required, "BH"); lin <- mo$OncotreeLineage; lin[is_m] <- "Mesothelioma"; nl <- table(lin); big <- names(nl)[nl >= 8]
SP$lineage_rank <- sapply(SP$TF, function(k) { m <- tapply(GE[, k], lin, median, na.rm = TRUE)[big]; rank(m)[["Mesothelioma"]] }); SP <- SP[order(SP$p_more_required), ]; write.csv(SP, file.path(OUT, sprintf("spec132_selected_TF_meso_specificity%s.csv", SFX)), row.names = FALSE)
cat(sprintf("\nselected TFs more required in mesothelioma than in the other %d lines (one-sided Wilcoxon; lineage rank among %d lineages with >= 8 lines, 1 = most required):\n", nrow(O), length(big))); print(head(SP[, c("TF", "meso_median", "other_median", "diff", "p_more_required", "fdr_more", "n_dep_meso", "pct_dep_meso", "pct_dep_other", "lineage_rank")], 14), digits = 2, row.names = FALSE)
cat("\nless required in mesothelioma (FDR < 0.05):\n"); print(SP[SP$fdr_less < 0.05, c("TF", "meso_median", "other_median", "diff", "p_less_required", "fdr_less")][order(SP$p_less_required[SP$fdr_less < 0.05]), ], digits = 2, row.names = FALSE)

spread <- function(y, gap) { o <- order(y); v <- y[o]; for (i in seq_along(v)[-1]) if (v[i] - v[i - 1] < gap) v[i] <- v[i - 1] + gap; y[o] <- v; y }
save_fig(paste0("fig48_selected_TFs_viability_meso", SFX), 6.6, 3.5, function() {
  par(mfrow = c(1, 2), family = "sans", mgp = c(2, 0.6, 0), tcl = -0.3); ttl <- function(x, y) { mtext(x, side = 3, adj = 0, line = 1.3, font = 2, cex = 0.72); mtext(y, side = 3, adj = 0, line = 0.35, cex = 0.52, col = INK2) }
  par(mar = c(3.4, 3.3, 2.6, 0.6)); L <- list(`68 selected TFs` = med[s], other = med[!s]); names(L)[2] <- BGLAB; boxplot(L, col = c(adjustcolor(SC, 0.55), "#d5d4cf"), border = INK2, outline = FALSE, las = 1, ylab = "median gene effect, 21 mesothelioma lines", cex.axis = 0.65, cex.lab = 0.7, ylim = range(med) + c(0, 0.22), xlim = c(0.5, 2.5), lwd = 0.8); yb <- max(med) + 0.08; segments(c(1, 1, 2), c(yb, yb - 0.04, yb - 0.04), c(2, 1, 2), c(yb, yb, yb), col = INK, lwd = 0.7); text(1.5, yb + 0.02, sprintf("p = %s", fp(w1$p.value)), pos = 3, cex = 0.6); abline(h = c(0, -0.5, -1), lty = c(1, 3, 2), col = c(INK, MUTED, MUTED), lwd = 0.7)
  set.seed(1); points(jitter(rep(2, sum(!s)), 8), med[!s], pch = 16, cex = 0.3, col = adjustcolor("grey40", 0.5)); xs <- jitter(rep(1, sum(s)), 8); points(xs, med[s], pch = 21, bg = SC, col = INK2, cex = 0.75, lwd = 0.6); lab <- sort(med[s])[1:7]; ly <- spread(lab, 0.105); xl <- xs[match(names(lab), names(med[s]))]; segments(xl + 0.04, lab, 1.3, ly, col = MUTED, lwd = 0.5); text(1.32, ly, names(lab), adj = 0, cex = 0.55, xpd = NA)
  ttl("A  viability after KO", sprintf("%d vs %d TFs; one-sided Wilcoxon (selected lower)", sum(s), sum(!s)))
  par(mar = c(3.4, 3.3, 2.6, 0.6)); y <- -log10(SP$p_more_required); plot(SP$diff, y, pch = 21, bg = ifelse(SP$fdr_more < 0.05, "#c8322b", ifelse(SP$p_more_required < 0.05, SC, "grey80")), col = INK2, cex = 0.95, lwd = 0.6, bty = "n", las = 1, xlab = "median gene effect: mesothelioma - other lines", ylab = "-log10 p (more required in mesothelioma)", cex.axis = 0.65, cex.lab = 0.7, xlim = range(SP$diff) + c(-0.03, 0)); abline(v = 0, lty = 2, col = INK, lwd = 0.7); abline(h = -log10(0.05), lty = 3, col = MUTED, lwd = 0.7)
  lab <- SP[SP$p_more_required < 0.05, ]; text(lab$diff, -log10(lab$p_more_required), lab$TF, pos = ifelse(lab$TF == "TEAD1", 4, 2), cex = 0.55, xpd = NA); legend("topright", c("FDR < 0.05", "p < 0.05", "n.s."), pch = 21, pt.bg = c("#c8322b", SC, "grey80"), bty = "n", cex = 0.55, pt.lwd = 0.6)
  ttl("B  mesothelioma-specific among the 68", sprintf("21 mesothelioma vs %d other lines; one-sided Wilcoxon, BH", nrow(O)))
})
